+// JIT copy of sgl-kernel's kernels/aot/csrc/allreduce/quick_all_reduce.h: the same DeviceComms and
+// buffers, launching the INT4 / INT8 TP4 two-shot of quick_all_reduce.cuh.
+#pragma once
+
+#include <hip/hip_runtime.h>
+
+#include "quick_all_reduce.cuh"
+#include <algorithm>
+#include <cstdio>
+#include <limits>
+#include <optional>
+#include <stdexcept>
+#include <vector>
+
+#define HIP_CHECK(err)                                                                               \
+  do {                                                                                               \
+    hipError_t err_ = (err);                                                                         \
+    if (err_ != hipSuccess) {                                                                        \
+      std::printf("HIP error %d at %s:%d. %s\n", err_, __FILE__, __LINE__, hipGetErrorString(err_)); \
+      throw std::runtime_error("HIP error");                                                         \
+    }                                                                                                \
+  } while (0)
+
+namespace quickreduce {
+
+template <typename AllReduceKernel, typename T>
+__global__ __quickreduce_launch_bounds_two_shot__ static void allreduce_prototype_twoshot(
+    T const* A,
+    T* B,
+    uint32_t N,
+    uint32_t num_blocks,
+    int rank,
+    uint8_t** dbuffer_list,
+    uint32_t data_offset,
+    uint32_t* d_flag_counters,
+    int64_t data_size_per_phase) {
+  int block = blockIdx.x;
+  int grid = gridDim.x;
+
+  // Kept in device memory, not a launch argument, so every CUDA-graph replay sees a fresh color.
+  uint32_t flag_color = d_flag_counters[blockIdx.x];
+
+  // Loaded once, before any remote store: on CDNA one vmcnt covers loads and stores, so a pointer
+  // load between remote stores would wait for their acknowledgment.
+  uint8_t* peer[AllReduceKernel::kWorldSize];
+  for (int r = 0; r < AllReduceKernel::kWorldSize; r++) {
+    peer[r] = dbuffer_list[r];
+  }
+  while (block < num_blocks) {
+    AllReduceKernel::run(A, B, N, block, rank, peer, data_offset, flag_color, data_size_per_phase);
+    block += grid;
+    flag_color++;
+  }
+  // The whole block ends up with the same value, so a single writer suffices.
